//! 构建 `native/webgal-video-render` 并把它静态链接进当前 Rust 目标。
//!
//! C++ 侧只有 Windows 实现: 其他平台留空 crate, 由 Ink 的 `cfg(windows)` 依赖排除。

use std::{
    path::{Path, PathBuf},
    process::Command,
};

/// 渲染器构建产物里被链接的静态库名 (与 CMake target 同名)。
const LIB_NAME: &str = "webgal-video-render";

fn main() {
    println!("cargo:rerun-if-changed=build.rs");

    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        println!("cargo:warning=webgal-video-render 只有 Windows 实现, 跳过 C++ 构建");
        return;
    }

    let manifest_dir = PathBuf::from(env_or_panic("CARGO_MANIFEST_DIR"));
    let workspace_root = manifest_dir
        .ancestors()
        .nth(2)
        .expect("crates/webgal-video-render-sys 应位于 workspace 下")
        .to_path_buf();
    let out_dir = PathBuf::from(env_or_panic("OUT_DIR"));

    for relative in [
        "CMakeLists.txt",
        "vcpkg.json",
        "cmake",
        "native/webgal-video-render/CMakeLists.txt",
        "native/webgal-video-render/src",
        "native/webgal-video-render/include",
        "native/webgal-video-render/shaders",
        "native/webgal-video-render/cmake",
    ] {
        println!(
            "cargo:rerun-if-changed={}",
            workspace_root.join(relative).display()
        );
    }
    println!("cargo:rerun-if-env-changed=VULKAN_SDK");
    println!("cargo:rerun-if-env-changed=VCPKG_ROOT");
    println!("cargo:rerun-if-env-changed=CMAKE_GENERATOR");

    let profile = env_or_panic("PROFILE");
    // rustc 在 MSVC 上始终链接 release CRT (msvcrt), 即使 cargo 走 dev profile;
    // 因此 C++ 侧不能用 Debug 配置 (/MDd 会产生 _calloc_dbg 之类的未解析符号),
    // 但又想保留调试信息, 所以 dev 用 RelWithDebInfo。
    let config = if profile == "debug" {
        "RelWithDebInfo"
    } else {
        "Release"
    };
    let build_dir = out_dir.join("cmake");

    configure(&workspace_root, &build_dir, config);
    build(&build_dir, config);

    let lib_dir = find_library(&build_dir, config);
    println!("cargo:rustc-link-search=native={}", lib_dir.display());
    println!("cargo:rustc-link-lib=static={LIB_NAME}");

    // 静态库的接口依赖: Vulkan 与 Media Foundation / WIC.
    if let Some(sdk) = std::env::var_os("VULKAN_SDK") {
        let lib = PathBuf::from(sdk).join("Lib");
        if lib.is_dir() {
            println!("cargo:rustc-link-search=native={}", lib.display());
        }
    }
    for library in [
        "vulkan-1",
        "windowscodecs",
        "ole32",
        "mfplat",
        "mfreadwrite",
        "mfuuid",
    ] {
        println!("cargo:rustc-link-lib={library}");
    }
}

fn env_or_panic(name: &str) -> String {
    std::env::var(name).unwrap_or_else(|_| panic!("缺少构建环境变量 {name}"))
}

fn configure(workspace_root: &Path, build_dir: &Path, config: &str) {
    let mut command = Command::new(cmake_program());
    command
        .arg("-S")
        .arg(workspace_root)
        .arg("-B")
        .arg(build_dir)
        .arg(format!("-DCMAKE_BUILD_TYPE={config}"))
        .arg(format!(
            "-DCMAKE_TOOLCHAIN_FILE={}",
            workspace_root.join("cmake/vcpkg-toolchain.cmake").display()
        ))
        .arg("-DVCPKG_TARGET_TRIPLET=x64-windows")
        // 与下面的手动 CMake 构建共用同一份 vcpkg 安装树, 避免重复编译依赖.
        .arg(format!(
            "-DVCPKG_INSTALLED_DIR={}",
            workspace_root.join("build/vcpkg_installed").display()
        ));

    // Rust 用 +crt-static 时 C++ 必须一起切到 /MT, 否则链接期会报 RuntimeLibrary 不匹配.
    if target_features()
        .iter()
        .any(|feature| feature == "crt-static")
    {
        command.arg("-DWEBGAL_RENDER_STATIC_CRT=ON");
    }

    run(command, "配置 C++ 渲染器失败");
}

fn build(build_dir: &Path, config: &str) {
    let mut command = Command::new(cmake_program());
    command
        .arg("--build")
        .arg(build_dir)
        .arg("--config")
        .arg(config)
        .arg("--target")
        .arg(LIB_NAME);
    run(command, "编译 C++ 渲染器失败");
}

fn run(mut command: Command, what: &str) {
    let status = command
        .status()
        .unwrap_or_else(|error| panic!("{what}: 无法启动 cmake ({error})"));
    if !status.success() {
        panic!("{what}: cmake 退出码 {status}");
    }
}

fn cmake_program() -> String {
    std::env::var("CMAKE").unwrap_or_else(|_| "cmake".to_owned())
}

fn target_features() -> Vec<String> {
    std::env::var("CARGO_CFG_TARGET_FEATURE")
        .unwrap_or_default()
        .split(',')
        .filter(|feature| !feature.is_empty())
        .map(str::to_owned)
        .collect()
}

/// 找出刚构建出的静态库目录 (兼容 Ninja 与 Visual Studio 多配置生成器).
fn find_library(build_dir: &Path, config: &str) -> PathBuf {
    let candidate_dir = build_dir.join("native").join(LIB_NAME);
    let file = format!("{LIB_NAME}.lib");

    for directory in [candidate_dir.join(config), candidate_dir.clone()] {
        if directory.join(&file).is_file() {
            return directory;
        }
    }

    let mut stack = vec![candidate_dir];
    while let Some(directory) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&directory) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else if path.file_name().is_some_and(|name| name == file.as_str()) {
                return path.parent().map(Path::to_path_buf).unwrap_or(directory);
            }
        }
    }

    panic!(
        "找不到 {file}: 请先执行 `cmake --preset windows-msvc-debug && cmake --build --preset windows-msvc-debug`"
    );
}
